import React, { Suspense, useEffect, useRef, useState } from 'react';
import '../gacha/Gacha.css';
import { Canvas, useFrame, useThree } from '@react-three/fiber'
import Model, { Ball } from "../gacha/model/Gumball_separated";
import { Physics } from '@react-three/cannon'
import { Vector3 } from "three";
import { Camera } from "../gacha/components/Camera";
import { useGLTF } from "@react-three/drei";
import { fireRandom, getRewardWithProbability, uuidv4 } from "../gacha/utils";

const PULL_HISTORY_KEY = "gachaPullHistory";

interface PullHistoryData {
  [rewardName: string]: { count: number; probability: number; isFirstReward: boolean; lastPulled: number };
}

function loadPullHistory(): PullHistoryData {
  const stored = localStorage.getItem(PULL_HISTORY_KEY);
  if (stored) {
    try {
      return JSON.parse(stored);
    } catch {
      return {};
    }
  }
  return {};
}

function savePullHistory(history: PullHistoryData): void {
  localStorage.setItem(PULL_HISTORY_KEY, JSON.stringify(history));
}

const states: Record<string, { next: string }> = {
  baseState: {
    next: "showingOverlay"
  },
  showingOverlay: {
    next: "showingOverlay2"
  },
  showingOverlay2: {
    next: "baseState"
  }
}

function Overlay() {
  const rewardRef = useRef<Object3D>();
  const {camera} = useThree();
  const [ballPosition, setBallPosition] = useState(new Vector3(0, 0, 0));
  const [ballRotation, setBallRotation] = useState(0);
  const {nodes} = useGLTF('/gumball_separated.gltf') as any
  const item = [
    nodes.Object_1020,
    nodes.Object_1020_1,
  ]
  const [hovering, setHovering] = useState(false);

  useFrame(() => {
    const d = new Vector3(0, 0, 0)
    const c = new Vector3(0, 0, 0)
    camera.getWorldDirection(d);
    camera.getWorldPosition(c);
    d.normalize()
      .multiplyScalar(5);
    c.add(d)
    setBallPosition(c);
    setBallRotation(ballRotation + 0.005)
  })

  return (
    <group position={ballPosition}>
      <mesh ref={rewardRef as any} geometry={item[0].geometry} material={item[0].material}
            rotation={[0, 0.1 * ballRotation, ballRotation]}
            onPointerOver={() => setHovering(true)}
            onPointerOut={() => setHovering(false)}
      >
        <meshStandardMaterial color={hovering ? 'hotpink' : 'orange'}/>
      </mesh>
      <mesh geometry={item[1].geometry} material={item[1].material}
            rotation={[0, 0.1 * ballRotation, ballRotation]}/>
    </group>
  )
}

function OtherOverlay(props: { text?: string }) {
  return (
    <div
      style={{
        position: "absolute",
        width: "100vw",
        height: "100vh",
        backgroundColor: "rgba(0, 0, 0, 0.8)",
        color: "white",
        zIndex: 1
      }}>
      <div style={{
        position: 'absolute', left: '50%', top: '50%',
        transform: 'translate(-50%, -50%)',
        fontSize: "50px",
        textAlign: "center"
      }}>
        {props.text || "Hello, world!"}
      </div>
    </div>
  )
}

type CollapseState = 'none' | 'one' | 'all';

function PullHistory(props: { history: PullHistoryData, onReset: () => void }) {
  const [collapseState, setCollapseState] = useState<CollapseState>(window.innerWidth < 768 ? 'one' : 'all');

  const cycleCollapseState = () => {
    setCollapseState(prev => {
      if (prev === 'none') return 'all';
      if (prev === 'all') return 'one';
      return 'none';
    });
  };

  const handleReset = () => {
    if (window.confirm("Reset everything? This will restart story rewards and clear pull history.")) {
      localStorage.removeItem("myCat");
      localStorage.removeItem("gachaTimestamp");
      localStorage.removeItem(PULL_HISTORY_KEY);
      props.onReset();
    }
  };

  const entries = Object.entries(props.history);
  const totalPulls = entries.reduce((sum, [, data]) => sum + data.count, 0);
  const sortedEntries = entries.sort((a, b) => (b[1].lastPulled || 0) - (a[1].lastPulled || 0));

  return (
    <div
      style={{
        position: "absolute",
        left: "20px",
        top: "20px",
        width: "320px",
        maxWidth: "calc(100vw - 40px)",
        maxHeight: "calc(100vh - 40px)",
        backgroundColor: "rgba(0, 0, 0, 0.7)",
        color: "white",
        borderRadius: "10px",
        padding: "15px",
        zIndex: 10,
        overflowY: "auto",
        pointerEvents: "auto"
      }}
      onClick={(e) => e.stopPropagation()}
    >
      <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", gap: "10px" }}>
        <button
          onClick={cycleCollapseState}
          style={{
            background: "transparent",
            border: "none",
            color: "white",
            cursor: "pointer",
            padding: "0",
            fontSize: "16px",
            display: "flex",
            alignItems: "center",
            gap: "8px"
          }}
        >
          <svg
            width="20"
            height="20"
            viewBox="0 0 24 24"
            fill="white"
            style={{
              transform: collapseState === 'none' ? "rotate(-90deg)" : collapseState === 'one' ? "rotate(-45deg)" : "rotate(0deg)",
              transition: "transform 0.2s ease"
            }}
          >
            <path d="M7 10l5 5 5-5z"/>
          </svg>
          <h3 style={{ margin: 0, fontSize: "16px" }}>
            Pulls ({totalPulls})
          </h3>
        </button>
        {collapseState === 'all' && (
          <button
            onClick={handleReset}
            style={{
              background: "#ff4444",
              border: "none",
              color: "white",
              padding: "5px 10px",
              borderRadius: "5px",
              cursor: "pointer",
              fontSize: "12px"
            }}
          >
            Reset All
          </button>
        )}
      </div>
      {collapseState !== 'none' && (
        <>
          <div style={{ borderBottom: "1px solid rgba(255,255,255,0.3)", margin: "10px 0" }} />
          {entries.length === 0 ? (
            <p style={{ color: "rgba(255,255,255,0.6)", fontStyle: "italic", margin: 0 }}>No pulls yet. Click to spin!</p>
          ) : (
            <ul style={{ listStyle: "none", padding: 0, margin: 0 }}>
              {(collapseState === 'one' ? sortedEntries.slice(0, 1) : sortedEntries).map(([name, data]) => (
                <li
                  key={name}
                  style={{
                    padding: "8px 0",
                    borderBottom: "1px solid rgba(255,255,255,0.1)",
                    fontSize: "14px"
                  }}
                >
                  <div style={{ display: "flex", justifyContent: "space-between", marginBottom: "4px" }}>
                    <span>{name}</span>
                    <span style={{
                      backgroundColor: "rgba(255,255,255,0.2)",
                      padding: "2px 8px",
                      borderRadius: "10px",
                      fontSize: "12px"
                    }}>
                      x{data.count}
                    </span>
                  </div>
                  <div style={{
                    fontSize: "12px",
                    color: data.isFirstReward ? "#ffd700" : getProbabilityColor(data.probability)
                  }}>
                    {data.isFirstReward ? "Story reward" : `${data.probability.toFixed(2)}% chance`}
                  </div>
                </li>
              ))}
              {collapseState === 'one' && entries.length > 1 && (
                <li style={{ padding: "8px 0", fontSize: "12px", color: "rgba(255,255,255,0.5)" }}>
                  +{entries.length - 1} more...
                </li>
              )}
            </ul>
          )}
        </>
      )}
    </div>
  );
}

function getProbabilityColor(probability: number): string {
  if (probability < 1) return "#ff4444";
  if (probability < 3) return "#ff8844";
  if (probability < 5) return "#ffcc44";
  return "rgba(255,255,255,0.6)";
}

export function GachaPage() {
  const [rewardText, setRewardText] = useState("Hello World!");
  const [myState, setMyState] = useState("baseState");
  const [handleDown, setHandleDown] = useState(false);
  const [childrenmap, setChildrenMap] = useState({} as Record<string, React.ReactNode>)
  const [pullHistory, setPullHistory] = useState<PullHistoryData>(() => loadPullHistory());
  const [isWaiting, setIsWaiting] = useState(false);
  const waitingTimeoutRef = useRef<ReturnType<typeof setTimeout> | null>(null);
  const confettiIntervalsRef = useRef<ReturnType<typeof setInterval>[]>([]);

  const childref = useRef<Record<string, React.ReactNode>>({})
  childref.current = childrenmap

  const setConfetti = () => {
    const interval1 = setInterval(() => {
      fireRandom()
    }, 1000)

    const interval2 = setInterval(() => {
      fireRandom()
    }, 1645)
    confettiIntervalsRef.current = [interval1, interval2];
  }

  const spawnBall = () => {
    const newChild = <Ball/>;
    const code = uuidv4();
    setChildrenMap({
      ...childrenmap,
      [code]: newChild
    })
    setTimeout(() => {
      let a = {
        ...childref.current,
      }
      delete a[code]
      setChildrenMap(a)
    }, 10000)
  }

  const reset = () => {
    confettiIntervalsRef.current.forEach(interval => {
      clearInterval(interval)
    })
    confettiIntervalsRef.current = [];
  }

  useEffect(() => {
    const onClick = () => {
      let nextState = states[myState].next

      if (myState === "baseState" && !isWaiting) {
        setHandleDown(true);
        setIsWaiting(true);
        spawnBall()
        waitingTimeoutRef.current = setTimeout(() => {
          setHandleDown(false);
          setIsWaiting(false);
          setMyState(nextState)
        }, 2000)
      } else if (myState === "baseState" && isWaiting) {
        // Skip the delay
        if (waitingTimeoutRef.current) {
          clearTimeout(waitingTimeoutRef.current);
          waitingTimeoutRef.current = null;
        }
        setHandleDown(false);
        setIsWaiting(false);
        setMyState(nextState)
      } else if (myState === "showingOverlay") {
        const reward = getRewardWithProbability();
        setRewardText(reward.name)
        setPullHistory(prev => {
          const updated = { ...prev };
          const now = Date.now();
          if (updated[reward.name]) {
            updated[reward.name] = { ...updated[reward.name], count: updated[reward.name].count + 1, lastPulled: now };
          } else {
            updated[reward.name] = { count: 1, probability: reward.probability, isFirstReward: reward.isFirstReward, lastPulled: now };
          }
          savePullHistory(updated);
          return updated;
        })
        setConfetti()
        let nextState = states[myState].next
        setMyState(nextState)
      } else if (myState === "showingOverlay2") {
        reset()
        setMyState(nextState)
      }
    }

    window.addEventListener("click", onClick);
    return () => {
      window.removeEventListener('click', onClick)
    }
  })

  return (
    <div className="gacha-container">
      <PullHistory history={pullHistory} onReset={() => setPullHistory({})} />
      {myState === "showingOverlay2" ? <OtherOverlay text={rewardText}/> : null}
      <Canvas style={{height: "100vh"}}>
        {myState === "showingOverlay" ? <Overlay/> : null}
        <ambientLight/>
        <pointLight position={[10, 10, 10]}/>
        <Suspense fallback={null}>
          <Physics gravity={[0, 0, -10]} defaultContactMaterial={{restitution: 0.5}}>
            <Model handleDown={handleDown} balls={Object.values(childrenmap)}/>
          </Physics>
        </Suspense>
        <Camera/>
      </Canvas>
    </div>
  );
}

useGLTF.preload('/gumball_separated.gltf')
