const key = "myCat";
const timestampKey = "gachaTimestamp";
// Change this date to force a reset for all users with older localStorage
const MINIMUM_VALID_TIMESTAMP = new Date("2025-11-25T00:00:00").getTime();

function checkAndResetIfStale(): void {
  const storedTimestamp = localStorage.getItem(timestampKey);

  if (!storedTimestamp || parseInt(storedTimestamp) < MINIMUM_VALID_TIMESTAMP) {
    // Reset story progress
    localStorage.removeItem(key);
    // Set new timestamp
    localStorage.setItem(timestampKey, Date.now().toString());
  }
}

export function whichFirstRewardToShow(): string {
  // Check for stale localStorage and reset if needed
  checkAndResetIfStale();

  const firstRewards = getFirstRewards();
  const lastReward = localStorage.getItem(key);
  let out: string;
  if (lastReward !== null) {
    const lastRewardInt = parseInt(lastReward);
    if (lastRewardInt >= firstRewards.length) {
      return ""
    }

    out = firstRewards[ lastRewardInt + 1]
    localStorage.setItem(key, (lastRewardInt + 1).toString())
  } else {
    localStorage.setItem(key, "0");
    out = firstRewards[0];
  }
  return out
}

// higher number = more common
const rewards: [string, number][] = [
    // simple rewards
    ['You get a hug', 1000],
    ['You get a kiss', 1000],
    ['One compliment from me', 1000],
    ['One dookie face card', 500],
    ['1 torment to the Bao', 500],
    
    ['A surprise gift', 10],
    ['A board game night', 10],
    ['A coffee date', 10],

    ['A short hike', 10],
    ['A long hike', 5],
    ['1 Jordan-Uber coupon', 10],
    ['1 free UberEats coupon', 10],
    ['A homemade dinner', 10],
    ['A dessert outing', 10],

    ['Bao thrown out in the rain', 1],
    ['1 free veto', 1],
    ['A fancy dinner date', 1],
    ['1 free Sephora basket', 1],
    ['1 fancy bouquet', 5],

    ['You get nothing', 1],
];

const totalWeight = rewards.reduce((sum, r) => sum + r[1], 0);

export interface RewardResult {
  name: string;
  probability: number;
  isFirstReward: boolean;
}

export function getRewardWithProbability(): RewardResult {
  const firstReward = whichFirstRewardToShow();
  if (firstReward) {
    return {
      name: firstReward,
      probability: 100,
      isFirstReward: true
    };
  }

  const threshold = Math.random() * totalWeight;

  let runningTotal = 0;
  for (let i = 0; i < rewards.length; ++i) {
    runningTotal += rewards[i][1];

    if (runningTotal >= threshold) {
      return {
        name: rewards[i][0] + "!",
        probability: (rewards[i][1] / totalWeight) * 100,
        isFirstReward: false
      };
    }
  }

  const lastReward = rewards[rewards.length - 1];
  return {
    name: lastReward[0] + "!",
    probability: (lastReward[1] / totalWeight) * 100,
    isFirstReward: false
  };
}

export function getReward() {
  return getRewardWithProbability().name;
}

export function uuidv4() {
  return 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, function (c) {
    const r = Math.floor(Math.random() * 16);
    const v = c === 'x' ? r : ((r & 0x3) | 0x8);
    return v.toString(16);
  });
}
